def backfill_armorias(apps, schema_editor):
    """Para cada Arma con organization_unit pero sin armory, crear (o reusar)
    un Armory default por unidad llamado '{unit.code}-PRINCIPAL' y mover el
    arma alli. Las armas que ya tienen armory se dejan tal cual."""
    Arma = apps.get_model('apipoligono', 'Arma')
    Armory = apps.get_model('armory', 'Armory')

    armas_sin_armory = Arma.objects.filter(armory__isnull=True, organization_unit__isnull=False)
    cache = {}  # (tenant_id, unit_id) -> Armory
    for arma in armas_sin_armory.select_related('organization_unit', 'tenant'):
        key = (arma.tenant_id, arma.organization_unit_id)
        if key not in cache:
            unit = arma.organization_unit
            armory, _ = Armory.objects.get_or_create(
                tenant_id=arma.tenant_id,
                code=f"{unit.code}-PRINCIPAL",
                defaults={
                    'organization_unit': unit,
                    'name': f"Almacen Principal {unit.name}",
                    'is_active': True,
                },
            )
            cache[key] = armory
        arma.armory = cache[key]
        arma.save(update_fields=['armory'])


